	return func(s *Source) {
		s.region = region
	}
}

// WithEndpoint configures the region for s3
func WithEndpoint(endpoint string) containers.Option[Source] {
	return func(s *Source) {
		s.endpoint = endpoint
	}
}

// WithPollInterval configures the interval in which we will restore
// the s3 fs.
